def extract(soup, sid):
    el=soup.find(id=sid)
    if el is None: return f'!! no existe {sid}'
    x=X(); x.sec=sid; x.lines.append(f'======== {sid} ========'); x.run(el); x.flush()
    return '\n'.join(x.lines)

if __name__=='__main__':
    soup=BeautifulSoup(open(sys.argv[1]).read(),'lxml')
    res=[extract(soup,sid) for sid in sys.argv[3:]]
    open(sys.argv[2],'w').write('\n\n'.join(res)); print(sys.argv[2], sum(len(r) for r in res), 'chars', sum(r.count('\n') for r in res),'lines')
